pub(crate) const STYLES: &str = r#"
.df-exploration{overflow-wrap:anywhere}.df-exploration .exploration-npc-text,.df-exploration .narration,.df-exploration .narration>div{min-width:0}
.df-exploration .stage{min-height:370px;padding-top:70px;padding-bottom:28px;gap:5vw}.df-exploration h1{font-size:clamp(44px,5vw,72px)}.df-exploration .description{font-size:18px}.df-exploration .lower{grid-template-columns:minmax(0,1fr) 280px;padding-bottom:25px}.df-exploration .exploration-interaction{width:min(1520px,92vw);margin:0 auto 28px;display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:28px}.df-exploration .exploration-npc,.df-exploration .exploration-actions{padding:26px;background:linear-gradient(125deg,#111c28f5,#07111df5);border:1px solid #c2a36b55;border-radius:5px;min-width:0}.df-exploration .exploration-npc{display:flex;align-items:flex-start;gap:22px}.df-exploration .exploration-npc[hidden]{display:none}.df-exploration .exploration-portrait{width:92px;height:114px;border-radius:45px 45px 5px 5px;border:1px solid #c2a36b99;object-fit:cover;flex:none}.df-exploration .exploration-portrait-failed{display:none}.df-exploration .exploration-npc-name{margin:0;font-size:27px;color:#efd5a7}.df-exploration .exploration-context{font:11px/1.6 system-ui,sans-serif;letter-spacing:1px;color:#a8becf;margin:7px 0 14px}.df-exploration .exploration-dialogue{font-size:19px;line-height:1.6;margin:0;color:#e8dfd0}.df-exploration .exploration-heading{margin:0 0 17px;font-size:24px;color:#f0d7ab}.df-exploration .exploration-choices{display:grid;gap:9px}.df-exploration .exploration-choice{border:1px solid #aabdd02e;background:#14213188;border-radius:3px;overflow:hidden}.df-exploration .exploration-choice button{display:block;width:100%;text-align:left;font:15px Georgia,serif;border:0;border-radius:0;color:#f0dfc3;padding:13px 16px;min-height:46px;background:#14223266}.df-exploration button:disabled{cursor:default;color:#9aa9b8;background:#0b142099;opacity:.8}.df-exploration .exploration-choice-detail,.df-exploration .exploration-choice-reason{font:11px/1.65 system-ui,sans-serif;color:#b9c5cd;padding:0 16px;margin:0 0 12px;overflow-wrap:anywhere}.df-exploration .exploration-choice-reason:empty{display:none}.df-exploration .exploration-choice-reason{color:#debda0}.df-exploration .df-ui-field{margin-top:22px}.df-exploration .df-ui-field label{display:block;font:12px/1.5 system-ui,sans-serif;color:#d8c6a7}.df-exploration .df-ui-field label span{display:block;margin-bottom:9px}.df-exploration input{width:100%;min-height:46px;border:1px solid #a5b9c955;border-radius:3px;background:#07111c;color:#f6ebd7;padding:12px;font:15px/1.5 system-ui,sans-serif}.df-exploration input:focus-visible{outline:2px solid #9ddbff;outline-offset:3px}.df-exploration input[aria-invalid=true]{border-color:#e5a188}.df-exploration .df-ui-feedback{font:12px/1.65 system-ui,sans-serif;color:#d8be91;margin:9px 0;overflow-wrap:anywhere}.df-exploration .exploration-submit{margin-top:9px;border-color:#c7a363;background:#69502255;color:#f1d49a}.df-exploration .exploration-empty{font:12px/1.7 system-ui,sans-serif;color:#abbac7}.df-exploration .exploration-art-fallback{display:none;margin:0 4vw 25px;font:12px/1.6 system-ui,sans-serif;color:#b9c8d5}.df-exploration.exploration-art-failed .scene-art{display:none}.df-exploration.exploration-art-failed .exploration-art-fallback{display:block}.df-exploration .exploration-checks{width:min(1520px,92vw);margin:20px auto 35px;padding:20px;border-top:1px solid #a9986944}.df-exploration .exploration-checks summary{min-height:44px;color:#d8bf8d;cursor:pointer}.df-exploration .exploration-fixture-controls{display:flex;flex-wrap:wrap;gap:8px}.df-exploration .exploration-check-status{font:12px/1.7 system-ui,sans-serif;color:#bfcddd}
@media(max-width:900px){.df-exploration .stage{grid-template-columns:minmax(0,1fr) 240px;gap:24px}.df-exploration .exploration-interaction{grid-template-columns:1fr}.df-exploration .lower{grid-template-columns:minmax(0,1fr) 240px}.df-exploration .exploration-npc{gap:18px}.df-exploration .exploration-portrait{width:76px;height:94px}}
@media(max-width:700px){.df-exploration .stage{display:block;padding-top:85px;min-height:0}.df-exploration .stage,.df-exploration .lower,.df-exploration .exploration-interaction{width:90vw}.df-exploration .scene-panel{margin-top:25px}.df-exploration .lower{display:flex}.df-exploration .exploration-npc,.df-exploration .exploration-actions{padding:20px}.df-exploration .exploration-npc{gap:15px}.df-exploration .exploration-dialogue{font-size:17px}.df-exploration .exploration-portrait{width:60px;height:76px}.df-exploration .exploration-npc-name{font-size:23px}.df-exploration .exploration-fixture-controls button{flex-basis:100%}.df-exploration .exploration-choice button{padding:14px}.df-exploration .exploration-submit{width:100%}}
"#;
